import {studentById,roster,keyFor,attendanceSummary} from './model.mjs';
import {renderMessageText} from './message-text.mjs';
export function createHomeTools(ui){
 const {esc,empty}=ui,button=(...args)=>ui.button(...args).replace('<button','<button type="button"'),$=s=>document.querySelector(s),days=new Map(),announcements=new Map(),messageCache=new Map();let outbox=null,composeDraft=null,sending=false,undo=[],redo=[],linkRange=null,readingFiles=false;
 async function api(path,options={}){const response=await fetch('/api/messages'+path,{credentials:'same-origin',cache:'no-store',...options,headers:{'Content-Type':'application/json',...options.headers}});const data=await response.json();if(!response.ok)throw Error(data.error||'Could not load messages.');return data;}
 function day(date){if(!days.has(date)){days.set(date,{loading:true});ui.attendanceApi('/day?'+new URLSearchParams({date})).then(data=>days.set(date,data)).catch(error=>days.set(date,{error:error.message})).finally(()=>{if(ui.route().path==='/home'&&ui.canRender())ui.render();});}return days.get(date);}
 function dayRecord(date,classId,period){return day(date).lessons?.find(l=>l.classId===classId&&l.period===period);}
 function badges(date,classId,period){const data=day(date);if(data.loading)return '<span class="muted">Loading attendance…</span>';if(data.error)return button('Retry attendance','home-attendance-refresh','','small');const context=dayRecord(date,classId,period);if(!context)return '<span class="badge draft">Not taken</span>';const summary=attendanceSummary(context.records),known=context.records.some(r=>r.status!=='Not Taken');if(!known)return '<span class="badge draft">Not taken</span>';return `<span class="home-attendance-badges">${button(summary.absent+' Absent','home-students',`data-class="${classId}" data-period="${period}" data-date="${date}" data-kind="absent"`,'attendance-badge absent')}${button(summary.late+' Late','home-students',`data-class="${classId}" data-period="${period}" data-date="${date}" data-kind="late"`,'attendance-badge late')}${summary.early?button(summary.early+' Left early','home-students',`data-class="${classId}" data-period="${period}" data-date="${date}" data-kind="early"`,'attendance-badge late'):''}</span>${!context.saved?'<small class="attendance-source">Earlier attendance · confirm in register</small>':summary.untaken?'<small class="attendance-source">Incomplete register</small>':''}`;}
 function refreshDay(){days.clear();if(ui.route().path==='/home'&&ui.canRender())ui.render();}
 function studentList(a){const {class:classId,period,date,kind}=a.dataset,context=dayRecord(date,classId,period),c=ui.classes().find(c=>c.id===classId);if(!context||!c)return;const records=context.records.filter(r=>kind==='absent'?r.status.startsWith('Absent'):kind==='late'?r.status.startsWith('Late'):r.status.startsWith('Left Early')),title=kind==='absent'?'Absent students':kind==='late'?'Late students':'Students who left early';ui.openDialog(title,`<p class="muted">${esc(c.name)} · ${esc(date)} · Period ${esc(period)}${context.saved?' · Saved register':' · From earlier saved attendance; confirm this lesson'}</p><div class="home-student-list">${records.length?records.map(r=>`<a href="#/student?id=${encodeURIComponent(r.studentId)}" data-action="home-open-student" data-id="${r.studentId}"><strong>${esc(studentById(r.studentId).name)}</strong><span>${esc(r.status)}${r.time?' · '+esc(r.time):''}</span></a>`).join(''):'<p class="muted">No students with this status are recorded for this lesson.</p>'}</div>`,`${button('Close','close')}<a class="btn primary" data-action="home-open-register" href="#/attendance?${new URLSearchParams({class:classId,date,period})}">Open register</a>`);}
 function classOptions(){return ui.classes().map(c=>`<label><input type="checkbox" data-message-class="${c.id}" ${composeDraft.classIds.includes(c.id)?'checked':''}>${esc(c.name)}</label>`).join('');}
 function composer(classId,saved){composeDraft=saved?structuredClone(saved):{classIds:classId?[classId]:ui.classes().map(c=>c.id),students:true,teachers:true,parents:false,copyMe:true,postToAnnouncements:true,pinned:false,subject:'',body:'',attachments:[],revision:0};undo=[];redo=[];
 ui.openDialog('Message My Classes',`<form id="class-message-form"><div class="message-local-label">Local test delivery · no external email is sent</div><div class="message-delivery"><div><h3>Delivery options</h3><label><input id="message-announcement" type="checkbox" ${composeDraft.postToAnnouncements?'checked':''}>Post to class announcements</label><label><input id="message-pin" type="checkbox" ${composeDraft.pinned?'checked':''} ${composeDraft.postToAnnouncements?'':'disabled'}>Pin to top</label></div><div><h3>Select classes</h3><details class="message-class-picker"><summary id="message-class-summary">Selected classes</summary><div><label class="message-all-classes"><input id="message-all-classes" type="checkbox" ${composeDraft.classIds.length===ui.classes().length?'checked':''}>All my classes</label>${classOptions()}</div></details></div></div><fieldset class="message-recipient-options"><legend>Included recipients</legend><label><input id="message-students" type="checkbox" ${composeDraft.students?'checked':''}>Students</label><label title="Parent contacts are not configured"><input type="checkbox" disabled>Parents of students</label><label title="Assigned teachers are included; no TAs are configured"><input id="message-teachers" type="checkbox" ${composeDraft.teachers?'checked':''}>Teacher and TA</label><label><input id="message-copy" type="checkbox" ${composeDraft.copyMe?'checked':''}>Send me a copy</label><small>Parent contacts and teaching assistants are not configured in this demo.</small></fieldset><p id="message-recipient-count" class="muted"></p><label class="field"><span>Subject</span><input id="message-subject" maxlength="160" value="${esc(composeDraft.subject)}" required></label><div class="field message-body-field"><label for="message-body">Message</label><div class="message-format-toolbar" role="toolbar" aria-label="Message formatting">${button('↶','message-format','data-format="undo" aria-label="Undo"','small')}${button('↷','message-format','data-format="redo" aria-label="Redo"','small')}${button('B','message-format','data-format="bold" aria-label="Bold"','small')}${button('I','message-format','data-format="italic" aria-label="Italic"','small')}${button('U','message-format','data-format="underline" aria-label="Underline"','small')}${button('↗ Link','message-format','data-format="link" aria-label="Insert link"','small')}${button('Clear','message-format','data-format="clear" aria-label="Clear formatting"','small')}${button('Preview','message-preview','','small')}</div><div id="message-link-controls" hidden><label class="field"><span>Link URL</span><input id="message-link-url" type="url" placeholder="https://…"></label>${button('Insert','message-insert-link','','small')}</div><textarea id="message-body" rows="6" maxlength="15000" placeholder="Write your class message…" required>${esc(composeDraft.body)}</textarea><div id="message-preview-panel" class="message-preview" hidden></div></div><div class="message-attachment-row"><label class="btn small">📎 Add attachment<input id="message-attachments" type="file" multiple hidden></label><small class="muted">Up to 3 files · 5 MB each · 10 MB total</small></div><div id="message-attachment-list"></div></form>`,`${button('Cancel','message-cancel')}<div class="actions">${button('Save draft','message-save-draft')}${button('Send test message','message-send','','primary')}</div>`,'CLASS COMMUNICATION');$('#dialog').classList.add('message-dialog');updateRecipientCount();drawAttachments();}
 function getComposer(){composeDraft={...composeDraft,classIds:[...document.querySelectorAll('[data-message-class]:checked')].map(el=>el.dataset.messageClass),postToAnnouncements:$('#message-announcement').checked,pinned:$('#message-announcement').checked&&$('#message-pin').checked,students:$('#message-students').checked,teachers:$('#message-teachers').checked,copyMe:$('#message-copy').checked,subject:$('#message-subject').value,body:$('#message-body').value};return composeDraft;}
 function updateRecipientCount(){getComposer();const selected=ui.classes().filter(c=>composeDraft.classIds.includes(c.id)),studentCount=composeDraft.students?new Set(selected.flatMap(c=>c.studentIds)).size:0,teachers=new Set(composeDraft.teachers?selected.map(c=>c.teacherId):[]);if(composeDraft.copyMe)teachers.add(ui.teacher().id);$('#message-class-summary').textContent=selected.length===ui.classes().length?'All my classes ('+selected.length+')':selected.length+' class'+(selected.length===1?'':'es')+' selected';$('#message-recipient-count').textContent=studentCount+' unique student'+(studentCount===1?'':'s')+' · '+teachers.size+' teacher'+(teachers.size===1?'':'s')+'/copies · '+selected.length+' class'+(selected.length===1?'':'es')+'. Recipients are deduplicated.';}
 function drawAttachments(){if(!$('#message-attachment-list'))return;$('#message-attachment-list').innerHTML=composeDraft.attachments.map((file,index)=>`<div><span>${esc(file.name)} · ${Math.ceil(file.size/1024)} KB</span>${button('Remove','message-remove-file',`data-index="${index}"`,'small')}</div>`).join('');}
 async function addFiles(input){readingFiles=true;try{const files=[...input.files];if(composeDraft.attachments.length+files.length>3)throw Error('Attach up to three files.');if(files.some(f=>f.size>5*1024*1024)||files.reduce((n,f)=>n+f.size,composeDraft.attachments.reduce((n,f)=>n+f.size,0))>10*1024*1024)throw Error('Files must be up to 5 MB each and 10 MB in total.');const added=await Promise.all(files.map(file=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve({name:file.name,type:file.type,size:file.size,data:String(reader.result).split(',')[1]});reader.onerror=()=>reject(Error('Could not read attachment.'));reader.readAsDataURL(file);})));composeDraft.attachments.push(...added);drawAttachments();ui.dialogDirty(true);}catch(error){ui.error(error.message);}finally{readingFiles=false;input.value='';}}
 function setBody(value,selection){const textarea=$('#message-body');undo.push(textarea.value);redo=[];textarea.value=value;composeDraft.body=value;ui.dialogDirty(true);if(selection){textarea.focus();textarea.setSelectionRange(selection[0],selection[1]);}updatePreview();}
 function format(kind){const textarea=$('#message-body'),start=textarea.selectionStart,end=textarea.selectionEnd,text=textarea.value,selected=text.slice(start,end);if(kind==='undo'||kind==='redo'){const from=kind==='undo'?undo:redo,to=kind==='undo'?redo:undo;if(!from.length)return;to.push(textarea.value);textarea.value=from.pop();composeDraft.body=textarea.value;ui.dialogDirty(true);updatePreview();return;}if(kind==='link'){linkRange={start,end,text:selected||'link'};$('#message-link-controls').hidden=false;$('#message-link-url').focus();return;}const marker={bold:'**',italic:'_',underline:'__'}[kind];if(kind==='clear'){const left=start===end?0:start,right=start===end?text.length:end;const clean=text.slice(left,right).replace(/\[([^\]]+)\]\(https?:\/\/[^)]+\)/g,'$1').replace(/\*\*|__/g,'').replace(/(^|\s)_([^_]+)_/g,'$1$2');setBody(text.slice(0,left)+clean+text.slice(right),[left,left+clean.length]);return;}const replacement=marker+(selected||'text')+marker;setBody(text.slice(0,start)+replacement+text.slice(end),[start+marker.length,start+replacement.length-marker.length]);}
 function updatePreview(){const panel=$('#message-preview-panel');if(panel&&!panel.hidden)panel.innerHTML=renderMessageText($('#message-body').value);}
 async function saveMessage(send){if(sending||!composeDraft)return;if(readingFiles){ui.error('Wait for the attachments to finish loading.');return;}const fromCancel=!$('#class-message-form'),draft=fromCancel?composeDraft:getComposer();if(!draft.classIds.length){ui.error('Select at least one class.');return;}if(send&&(!draft.subject.trim()||!draft.body.trim())){ui.error('Add a subject and message before sending.');return;}sending=true;const controls=[...$('#dialog').querySelectorAll('input,textarea,button')].map(el=>({el,disabled:el.disabled}));controls.forEach(({el})=>el.disabled=true);try{const {message}=await api('/save',{method:'PUT',body:JSON.stringify({...draft,status:send?'sent':'draft',expectedRevision:draft.revision})});messageCache.set(message.id,message);outbox=null;announcements.clear();if(send){ui.dialogDirty(false);ui.closeDialog(true);composeDraft=null;ui.render();ui.toast('Test message saved locally'+(message.postToAnnouncements?' and posted to class announcements.':'.'));}else{composeDraft={...message};ui.dialogDirty(false);if(fromCancel){ui.closeDialog(true);composeDraft=null;ui.render();}else drawAttachments();ui.toast('Message draft saved on the local server.');}}catch(error){ui.error(error.message);}finally{sending=false;controls.forEach(({el,disabled})=>{if(el.isConnected)el.disabled=disabled;});}}
 function page(params){const id=params.get('id');if(id){if(!messageCache.has(id)){messageCache.set(id,{loading:true});api('/message?'+new URLSearchParams({id})).then(data=>messageCache.set(id,data.message)).catch(error=>messageCache.set(id,{error:error.message})).finally(()=>{if(ui.route().path==='/messages'&&ui.canRender())ui.render();});}const message=messageCache.get(id);if(message.loading)return empty('Loading message','');if(message.error)return '<div class="error">'+esc(message.error)+'</div>';return `<div class="page-heading"><div><div class="eyebrow">LOCAL CLASS MESSAGE · ${message.status.toUpperCase()}</div><h1>${esc(message.subject||'Untitled draft')}</h1><p>${esc(message.author)} · ${new Date(message.updatedAt).toLocaleString('en-GB',{timeZone:'Asia/Tashkent'})}</p></div><div class="actions"><a class="btn small" href="#/messages">Messages</a>${message.status==='draft'?button('Edit draft','message-edit',`data-id="${message.id}"`,'primary small'):''}</div></div><section class="panel"><div class="panel-body"><p class="muted">${message.classIds.map(id=>esc(ui.classes().find(c=>c.id===id)?.name||id)).join(' · ')}<br>${message.recipientStudentIds.length} students · ${message.recipientTeacherIds.length} teacher${message.recipientTeacherIds.length===1?'':'s'}/copies · local test delivery</p><div class="message-rendered">${renderMessageText(message.body)}</div>${message.attachments.map(file=>`<a class="btn small" href="/api/messages/attachment?${new URLSearchParams({messageId:message.id,attachmentId:file.id})}">📎 ${esc(file.name)}</a>`).join('')}</div></section>`;}
 if(!outbox){outbox={loading:true};api('/owned').then(data=>{outbox=data;data.messages.forEach(m=>messageCache.set(m.id,m));}).catch(error=>outbox={error:error.message}).finally(()=>{if(ui.route().path==='/messages'&&ui.canRender())ui.render();});}return `<div class="page-heading"><div><div class="eyebrow">CLASS COMMUNICATION</div><h1>Messages</h1><p>Saved drafts, sent test messages and class announcements.</p></div>${button('Message My Classes','message-compose','','primary')}</div><div class="notice">Local test delivery. External email and parent accounts are not connected.</div>${outbox.loading?empty('Loading messages',''):outbox.error?'<div class="error">'+esc(outbox.error)+'</div>':outbox.messages.length?`<section class="panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Subject</th><th>Classes / recipients</th><th>Status</th><th>Updated</th></tr></thead><tbody>${outbox.messages.map(m=>`<tr><td><a class="assessment-link" href="#/messages?id=${m.id}">${esc(m.subject||'Untitled draft')}</a>${m.pinned?'<small>📌 Pinned announcement</small>':''}</td><td>${m.classIds.length} classes · ${m.recipientStudentIds.length} students</td><td>${m.status==='draft'?'Draft':'Sent locally'}</td><td>${new Date(m.updatedAt).toLocaleString('en-GB',{timeZone:'Asia/Tashkent'})}</td></tr>`).join('')}</tbody></table></div></section>`:empty('No messages yet','Use Message My Classes to write a message or class announcement.')}`;}
 function classAnnouncements(c){if(!announcements.has(c.id)){announcements.set(c.id,{loading:true});api('/class?'+new URLSearchParams({classId:c.id})).then(data=>{announcements.set(c.id,data);data.messages.forEach(m=>messageCache.set(m.id,m));}).catch(error=>announcements.set(c.id,{error:error.message})).finally(()=>{if(ui.route().path==='/classes'&&ui.route().params.get('class')===c.id&&ui.canRender())ui.render();});}const data=announcements.get(c.id);return `<section class="panel class-announcements"><div class="panel-head"><h2>Class announcements</h2>${button('Message this class','message-compose',`data-class="${c.id}"`,'small')}</div>${data.loading?'<div class="panel-body muted">Loading announcements…</div>':data.error?'<div class="panel-body error">'+esc(data.error)+'</div>':data.messages.length?data.messages.map(m=>`<div class="class-announcement"><a href="#/messages?id=${m.id}"><strong>${m.pinned?'📌 ':''}${esc(m.subject)}</strong></a><p>${renderMessageText(m.body.slice(0,140))}${m.body.length>140?'…':''}</p><small>${esc(m.author)} · ${new Date(m.sentAt).toLocaleDateString('en-GB',{timeZone:'Asia/Tashkent'})}</small></div>`).join(''):'<div class="panel-body muted">No announcements yet.</div>'}</section>`;}
 function action(action,a){if(action==='home-attendance-refresh'){refreshDay();return true;}if(action==='home-students'){studentList(a);return true;}if(action==='home-open-student'||action==='home-open-register'){ui.closeDialog(true);return true;}if(action==='message-compose'){composer(a.dataset.class);return true;}if(action==='message-edit'){composer(null,messageCache.get(a.dataset.id));return true;}if(action==='message-format'){format(a.dataset.format);return true;}if(action==='message-preview'){const panel=$('#message-preview-panel');panel.hidden=!panel.hidden;updatePreview();return true;}if(action==='message-insert-link'){const url=$('#message-link-url').value.trim();if(!/^https?:\/\/\S+$/i.test(url)){ui.error('Enter a link starting with https:// or http://.');return true;}const text=$('#message-body').value,range=linkRange||{start:text.length,end:text.length,text:'link'};setBody(text.slice(0,range.start)+'['+range.text+']('+url+')'+text.slice(range.end));$('#message-link-controls').hidden=true;return true;}if(action==='message-remove-file'){composeDraft.attachments.splice(Number(a.dataset.index),1);drawAttachments();ui.dialogDirty(true);return true;}if(action==='message-save-draft'||action==='message-send'){void saveMessage(action==='message-send');return true;}if(action==='message-cancel'){if(!ui.hasDialogChanges()){composeDraft=null;ui.closeDialog(true);return true;}getComposer();ui.openDialog('Keep this message?', '<p>Your message has not been sent. Save a draft or discard these edits.</p>',button('Keep editing','message-keep')+button('Discard','message-discard')+button('Save draft','message-save-draft','','primary'));ui.dialogDirty(true);return true;}if(action==='message-keep'){composer(null,composeDraft);ui.dialogDirty(true);return true;}if(action==='message-discard'){composeDraft=null;ui.dialogDirty(false);ui.closeDialog(true);return true;}return false;}
 function input(t){if(t.id==='message-body'){undo.push(composeDraft.body);redo=[];composeDraft.body=t.value;updatePreview();}if(t.closest('#class-message-form')){getComposer();ui.dialogDirty(true);}}
 function change(t){if(t.id==='message-attachments'){void addFiles(t);return;}if(t.id==='message-all-classes')document.querySelectorAll('[data-message-class]').forEach(el=>el.checked=t.checked);if(t.hasAttribute('data-message-class'))$('#message-all-classes').checked=[...document.querySelectorAll('[data-message-class]')].every(el=>el.checked);if(t.id==='message-announcement'){$('#message-pin').disabled=!t.checked;if(!t.checked)$('#message-pin').checked=false;}if(t.closest('#class-message-form')){updateRecipientCount();ui.dialogDirty(true);}}
 return{day,dayRecord,badges,refreshDay,action,input,change,page,classAnnouncements,api};
}
